  $('#worldHeadings').innerHTML=layout.headings.map(h=>'<span style="left:'+h.x+'px;top:'+h.y+'px">'+escapeHTML(h.label)+'</span>').join('');$('#worldLines').innerHTML=this.edgeMarkup(layout.nodes,layout.edges,'map');
  $('#worldNodes').querySelectorAll('[data-world-node]').forEach(el=>{const ref=el.dataset.worldNode;el.onclick=()=>{if(this.ignoreClick===ref){this.ignoreClick=null;return}this.select(ref)};el.ondblclick=()=>this.focus(ref);el.onpointerdown=e=>{if(e.button!==0)return;e.stopPropagation();const n=this.layout.nodes.find(n=>n.ref===ref);this.selected={kind:'entity',id:ref};this.inspect();canvasCapture(e);this.drag={ref,x:e.clientX,y:e.clientY,position:{x:n.x,y:n.y},moved:false}};el.onkeydown=e=>{if(!e.shiftKey||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();e.stopPropagation();const n=this.layout.nodes.find(n=>n.ref===ref);this.moveNode(ref,n.x+(e.key==='ArrowRight'?20:e.key==='ArrowLeft'?-20:0),n.y+(this.settings.view==='network'?(e.key==='ArrowDown'?20:e.key==='ArrowUp'?-20:0):0));this.saveSettings();$('#worldNodes [data-world-node="'+CSS.escape(ref)+'"]')?.focus({preventScroll:true})}});
