 async showOnBoard(characterId){let card=ArchiveModel.board(this.book()).cards.find(c=>c.characterId===characterId);if(!card){const id=crypto.randomUUID();await this.commit(b=>{const board=ArchiveModel.board(b),n=board.cards.length;return {...b,board:{...board,cards:[...board.cards,{id,type:'character',characterId,title:WorldModel.entity(WorldModel.get(b),'c:'+characterId)?.name||'Character',body:'',color:'#7890a8',x:(n%4)*290,y:Math.floor(n/4)*230,w:260,h:210}]}}});card=ArchiveModel.board(this.book()).cards.find(c=>c.id===id)}setWorkspaceTab('board');Board.focus(card)},
